    const result = runTodoCommand(['add', 'buy milk']);
    expect(result.stderr.toString()).toBe('');
    expect(result.stdout.toString()).toBe('');
    expect(getTodoFileContent()).toEqual(['buy milk']);
  });

  await test('appends to an existing list', () => {
    setTodoFileContent(['buy milk']);
    const result = runTodoCommand(['add', 'buy eggs']);
    expect(result.stderr.toString()).toBe('');
    expect(result.stdout.toString()).toBe('');
    expect(getTodoFileContent()).toEqual(['buy milk', 'buy eggs']);
