const todoPath = path.resolve(__dirname, "../todo.json");

function runCommand(text) {
  return require("child_process").execSync(`node ${path.resolve(__dirname, "..")}/bin/todo.js add ${text}`, { cwd: __dirname }).toString().trim();
}

function cleanup() {
  try {
    fs.unlinkSync(todoPath);
  } catch (e) {
    // Ignore
  }
}

describe("todo-cli", () => {
  before(() => {
    cleanup();
  });

  after(() => {
    cleanup();
  });

  it("should add a todo item", () => {
    runCommand("Buy groceries");
    const todos = JSON.parse(fs.readFileSync(todoPath, "utf8"));
    assert.deepStrictEqual(todos, ["Buy groceries"]);
  });

  it("should handle empty input", () => {
    try {
      runCommand("");
    } catch (e) {
      assert.strictEqual(e.stderr, "Usage: node bin/todo.js add <text>\n");
    }
  });
});"}}}
